#include <stdio.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* reverse(Node* head) {
    Node* prev = NULL;
    Node* curr = head;
    while (curr) {
        Node* next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

int main() {
    Node n5 = {5, NULL};
    Node n4 = {4, &n5};
    Node n3 = {3, &n4};
    Node n2 = {2, &n3};
    Node n1 = {1, &n2};

    Node* head = reverse(&n1);
    while (head) {
        printf("%d", head->data);
        head = head->next;
    }
    return 0;
}

